import requests

response = requests.get(
    "https://api.themoviedb.org/3/search/movie",
    params={"query": "Titanic"},
)
response.raise_for_status()
movies = response.json().get("results", [])
movie = next((item for item in movies if item.get("title") == "Titanic"), movies[0] if movies else None)

if movie:
    credits_response = requests.get(
        f"https://api.themoviedb.org/3/movie/{movie['id']}/credits"
    )
    credits_response.raise_for_status()
    cast = credits_response.json().get("cast", [])
    lead_actor = next(
        (person for person in cast if person.get("character") == "Jack Dawson"),
        cast[0] if cast else None,
    )

    if lead_actor:
        person_response = requests.get(
            f"https://api.themoviedb.org/3/person/{lead_actor['id']}"
        )
        person_response.raise_for_status()
        person = person_response.json()
        print({
            "name": person.get("name"),
            "profile_path": person.get("profile_path"),
            "profile_url": (
                f"https://image.tmdb.org/t/p/w500{person['profile_path']}"
                if person.get("profile_path")
                else None
            ),
        })

