import requests

API_KEY = "YOUR_TMDB_API_KEY"
BASE_URL = "https://api.themoviedb.org/3"

# The Hobbit films are not a collection, so retrieve release dates for the three movies.
movie_ids = {
    "The Hobbit: An Unexpected Journey": 49051,
    "The Hobbit: The Desolation of Smaug": 57158,
    "The Hobbit: The Battle of the Five Armies": 122917,
}

for title, movie_id in movie_ids.items():
    response = requests.get(
        f"{BASE_URL}/movie/{movie_id}/release_dates",
        params={"api_key": API_KEY},
    )
    response.raise_for_status()
    data = response.json()

    print(title)
    for country in data.get("results", []):
        for release in country.get("release_dates", []):
            print(country.get("iso_3166_1"), release.get("release_date"), release.get("type"))

