import requests

BASE_URL = "https://api.themoviedb.org/3"
API_KEY = "YOUR_TMDB_API_KEY"

def search_tv(query):
    response = requests.get(
        f"{BASE_URL}/search/tv",
        params={"api_key": API_KEY, "query": query},
    )
    response.raise_for_status()
    return response.json()["results"]

def search_movie(query):
    response = requests.get(
        f"{BASE_URL}/search/movie",
        params={"api_key": API_KEY, "query": query},
    )
    response.raise_for_status()
    return response.json()["results"]

def get_tv_crew(series_id):
    response = requests.get(
        f"{BASE_URL}/tv/{series_id}/credits",
        params={"api_key": API_KEY},
    )
    response.raise_for_status()
    return response.json().get("crew", [])

def get_movie_crew(movie_id):
    response = requests.get(
        f"{BASE_URL}/movie/{movie_id}/credits",
        params={"api_key": API_KEY},
    )
    response.raise_for_status()
    return response.json().get("crew", [])

twin_peaks = next(
    show for show in search_tv("Twin Peaks")
    if show.get("name") == "Twin Peaks"
)
mulholland_drive = next(
    movie for movie in search_movie("Mulholland Drive")
    if movie.get("title") == "Mulholland Drive"
)

twin_peaks_directors = {
    person["name"]
    for person in get_tv_crew(twin_peaks["id"])
    if person.get("job") == "Director"
}
mulholland_drive_directors = {
    person["name"]
    for person in get_movie_crew(mulholland_drive["id"])
    if person.get("job") == "Director"
}

print(bool(twin_peaks_directors & mulholland_drive_directors))
print("Twin Peaks directors:", sorted(twin_peaks_directors))
print("Mulholland Drive directors:", sorted(mulholland_drive_directors))

import requests

BASE_URL = "https://api.themoviedb.org/3"
API_KEY = "YOUR_TMDB_API_KEY"

# Find Mulholland Drive, then identify its director and retrieve their TV credits.
movie_results = requests.get(
    f"{BASE_URL}/search/movie",
    params={"api_key": API_KEY, "query": "Mulholland Drive"},
).json().get("results", [])

movie = next(
    (item for item in movie_results if item.get("title") == "Mulholland Drive"),
    movie_results[0] if movie_results else None,
)

if movie:
    credits = requests.get(
        f"{BASE_URL}/movie/{movie['id']}/credits",
        params={"api_key": API_KEY},
    ).json()
    director = next(
        (person for person in credits.get("crew", []) if person.get("job") == "Director"),
        None,
    )

    if director:
        tv_credits = requests.get(
            f"{BASE_URL}/person/{director['id']}/tv_credits",
            params={"api_key": API_KEY},
        ).json()
        directed_series = [
            credit.get("name")
            for credit in tv_credits.get("crew", [])
            if credit.get("job") == "Director" and credit.get("name")
        ]
        print(sorted(set(directed_series)))

